<?php
require 'config.php'; require 'functions.php'; require_officer();
$idRaw = $_GET['id'] ?? '0';
$id = is_string($idRaw) ? filter_var($idRaw, FILTER_VALIDATE_INT, ['options' => ['min_range' => 0]]) : false;
if ($id === false) { http_response_code(400); exit('Invalid announcement.'); }
$post=null;
if($id){$s=$pdo->prepare("SELECT * FROM announcements WHERE id=? AND deleted_at IS NULL");$s->execute([$id]);$post=$s->fetch();if(!$post) { http_response_code(404); exit('Announcement not found.'); }}
$tagNames = $post ? implode(', ', get_announcement_tags($pdo, $id)) : '';
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $post?'Edit':'New' ?> Announcement · CS3B</title><link rel="icon" href="assets/brand/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css?v=<?=asset_version("assets/style.css")?>"><script src="assets/theme.js?v=<?=asset_version("assets/theme.js")?>" defer></script></head><body>
<header class="top"><div class="site-brand-wrap"><a href="./" class="site-brand" aria-label="Pilimon Bulletin home"><img class="site-brand__logo" src="assets/brand/pilimon-bulletin-wordmark-light.svg" alt="Pilimon Bulletin"><span class="site-brand__meta" aria-hidden="true"></span></a></div><nav><a href="./">Home</a><a href="calendar">Calendar</a><a href="officers">Officers</a><a href="report-a-problem">Report a problem</a><a href="dashboard">Dashboard</a><a href="profile">My Profile</a><a href="change-password">Change Password</a><a href="logout">Logout</a></nav></header><main class="container narrow"><div class="dashhead"><h1><?= $post?'Edit':'New' ?> Announcement</h1><a href="dashboard">← Dashboard</a></div>
<form class="card form" action="save-announcement" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="version" value="<?=e($post['version']??1)?>">
<label>Title<input name="title" maxlength="200" value="<?=e($post['title']??'')?>" required></label><label>Category<select name="category"><?php foreach(['General','Academic','Schedule','Event','Reminder','Other'] as $c): ?><option <?=($post['category']??'General')===$c?'selected':''?>><?=$c?></option><?php endforeach; ?></select></label>
<label>Tags (optional)<input name="tags" maxlength="420" value="<?=e($tagNames)?>" placeholder="Orientation, enrollment"><span class="field-note">Up to 10 tags, separated by commas.</span></label><fieldset class="date-fields"><legend>Event (optional)</legend><label>Event date<input type="date" name="event_date" value="<?=e($post['event_date']??'')?>"></label><label class="checkbox-field"><input type="checkbox" name="event_all_day" value="1" <?=!isset($post['event_all_day'])||$post['event_all_day']?'checked':''?>> All day</label><label>Starts at<input type="time" name="event_start" value="<?=e(isset($post['event_start'])?substr($post['event_start'],0,5):'')?>"></label><label>Ends at (optional)<input type="time" name="event_end" value="<?=e(isset($post['event_end'])?substr($post['event_end'],0,5):'')?>"></label></fieldset><fieldset class="date-fields"><legend>Deadline (optional)</legend><label>Deadline date<input type="date" name="deadline_date" value="<?=e($post['deadline_date']??'')?>"></label><label class="checkbox-field"><input type="checkbox" name="deadline_all_day" value="1" <?=!isset($post['deadline_all_day'])||$post['deadline_all_day']?'checked':''?>> All day</label><label>Deadline time<input type="time" name="deadline_time" value="<?=e(isset($post['deadline_time'])?substr($post['deadline_time'],0,5):'')?>"></label></fieldset><label>Caption / Body<textarea name="caption" rows="9"><?=e($post['caption']??'')?></textarea></label><label>Image (optional)<input type="file" name="image" accept=".jpg,.jpeg,.png,.webp"></label><label>Embedded video URL (YouTube/Vimeo, optional)<input name="video_url" type="url" placeholder="https://youtube.com/watch?v=..." value="<?=e($post['video_url']??'')?>"></label><label>Publication<select name="status" id="announcement-status"><option value="draft" <?=($post['status']??'')==='draft'?'selected':''?>>Save as draft</option><option value="published" <?=($post['status']??'published')==='published'?'selected':''?>>Publish now</option><option value="scheduled" <?=($post['status']??'')==='scheduled'?'selected':''?>>Schedule publication</option></select></label><label>Publish at<input type="datetime-local" name="publish_at" id="publish-at" value="<?=e(campus_datetime_input($post['publish_at']??null))?>"><span class="field-note">Campus time: Asia/Manila. Required for scheduled announcements.</span></label><label>Expire at (optional)<input type="datetime-local" name="expires_at" value="<?=e(campus_datetime_input($post['expires_at']??null))?>"><span class="field-note">Expiration hides the announcement; it is separate from its event date or deadline.</span></label><?php if($post): ?><p><a href="./?id=<?=$id?>" target="_blank" rel="noopener">Preview announcement</a> · <a href="announcement-history?id=<?=$id?>">Version history</a></p><?php endif; ?><button class="primary">Save Announcement</button></form></main><script>
const form = document.querySelector('.form');
const statusField = document.querySelector('#announcement-status');
const titleField = form.querySelector('[name="title"]');
const captionField = form.querySelector('[name="caption"]');
const publishField = document.querySelector('#publish-at');
function updateLifecycleFields() {
	const needsContent = statusField.value !== 'draft';
	titleField.required = needsContent;
	captionField.required = needsContent;
	publishField.required = statusField.value === 'scheduled';
}
statusField.addEventListener('change', updateLifecycleFields);
updateLifecycleFields();
</script></body></html>
